"""Write ``typings/colosseum/__init__.pyi`` from discovered namespaces."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .core_exports import CORE_EXPORT_LINES

CATALOG_FILENAME = "colosseum_namespaces.json"


def render_stub(namespaces: dict[str, str]) -> str:
    """Render a complete ``colosseum`` stub with core exports + namespace aliases."""

    lines: list[str] = [
        "# AUTO-GENERATED by colosseum-linter — do not edit",
        "# Regenerated when you run: Colosseum: Refresh namespace stubs",
        "from __future__ import annotations",
        "",
        *CORE_EXPORT_LINES,
        "",
    ]

    if namespaces:
        lines.append("# Plugin namespaces (from colosseum.plugins entry points)")
        for name in sorted(namespaces):
            module_name = namespaces[name]
            # module.__name__ is a dotted path (e.g. colosseum_equipment.api)
            lines.append(f"import {module_name} as {name}")
        lines.append("")
    else:
        lines.append("# No colosseum.plugins namespaces discovered in this environment")
        lines.append("")

    return "\n".join(lines)


def write_stub(out_dir: Path, namespaces: dict[str, str]) -> Path:
    """Write stubs under ``out_dir/colosseum/__init__.pyi`` and return that path."""

    package_dir = out_dir / "colosseum"
    package_dir.mkdir(parents=True, exist_ok=True)
    stub_path = package_dir / "__init__.pyi"
    stub_path.write_text(render_stub(namespaces), encoding="utf-8")
    return stub_path


def write_catalog(out_dir: Path, catalog: dict[str, Any]) -> Path:
    """Write diagnostic catalog JSON next to generated stubs."""

    out_dir.mkdir(parents=True, exist_ok=True)
    catalog_path = out_dir / CATALOG_FILENAME
    catalog_path.write_text(json.dumps(catalog, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return catalog_path
